  y=190;doc.setFont('helvetica','bold');doc.setFontSize(8);doc.setTextColor(8,133,182);doc.text('SUMMARY',left,y);doc.setTextColor(23,43,61);doc.setFontSize(14);doc.text(doc.splitTextToSize(ticket.title||'Support ticket',right-left),left,y+21);y+=55;doc.setFillColor(221,239,247);doc.rect(left,y,right-left,26,'F');doc.setFontSize(8);doc.text('DESCRIPTION',left+9,y+17);doc.text('HOURS',390,y+17,{align:'right'});doc.text('RATE',475,y+17,{align:'right'});doc.text('TOTAL',right-8,y+17,{align:'right'});y+=38;doc.setFont('helvetica','normal');doc.setFontSize(10);doc.text('Billable helpdesk service',left+9,y);doc.text(hours.toFixed(2),390,y,{align:'right'});doc.text(money(ticket.hourlyRate||0),475,y,{align:'right'});doc.setFont('helvetica','bold');doc.text(money(billing.total),right-8,y,{align:'right'});y+=30;doc.setDrawColor(215,226,232);doc.line(left,y-12,right,y-12);
