  useEffect(()=>{const cells=[...document.querySelectorAll('.subscription-detail-screen .subscription-ticket-row:not(.subscription-ticket-head)>:last-child')];cells.forEach((cell,index)=>{const ticket=tickets[index];if(ticket)cell.textContent=decimalHours((ticket.timeEntries||[]).reduce((sum,entry)=>sum+Number(entry.minutes||0),0))})},[tickets.map(ticket=>`${ticket.id}:${(ticket.timeEntries||[]).map(entry=>`${entry.id}:${entry.minutes}`).join(',')}`).join('|')]);
