function Clients({data,open}) { return data.clients.length?<section className="panel page-panel client-list"><div className="client-list-row client-list-head"><span>Client</span><span>Location</span><span>Invoices</span><span>Paid</span><span>Due</span><span></span></div>{data.clients.map(client=>{const invoices=data.invoices.filter(invoice=>invoice.clientId===client.id),invoiceIds=new Set(invoices.map(invoice=>invoice.id)),payments=data.payments.filter(payment=>invoiceIds.has(payment.invoiceId));return <button type="button" className="client-list-row" key={client.id} onClick={()=>open(client)}><span><b className="client-avatar">{client.name[0]}</b><strong>{client.name}</strong></span><span className="client-location">{client.address&&<small>{client.address}</small>}<b>{client.city}, {client.state} {client.zip}</b></span><span>{invoices.length}</span><span>{money(payments.reduce((sum,payment)=>sum+payment.amount,0))}</span><span>{money(invoices.reduce((sum,invoice)=>sum+invoice.balance,0))}</span><span>Open client →</span></button>})}</section>:<Empty title="No clients yet" text="Clients include their service location, optional hourly rate, invoices, estimates, payments made, and balance due."/>; }

