const coreAssetSections=['All','Configurations','Passwords','Applications','Printing','Wireless','LAN','WAN'];
const coreAssetCategory=asset=>{
  if(asset.assetCategory)return asset.assetCategory;
  const value=[asset.type,asset.name,asset.hostname,asset.manufacturer,asset.model,asset.operatingSystem,asset.notes].filter(Boolean).join(' ').toLowerCase();
  if(asset.isWireless||/wireless|wi-?fi|ssid/.test(value))return 'Wireless';
  if(/printer|printing|copier|plotter|scanner/.test(value))return 'Printing';
  if(/\bwan\b|internet|modem|gateway|edge router|firewall/.test(value))return 'WAN';
  if(/\blan\b|switch|access point|wireless|wi-?fi|network controller/.test(value))return 'LAN';
  if(/application|software|license|saas|microsoft 365|office 365/.test(value))return 'Applications';
  return 'Configurations';
};

