  WAN:[['carrier','Carrier / ISP'],['circuitId','Circuit ID'],['serviceType','Service type'],['bandwidthDown','Download bandwidth'],['bandwidthUp','Upload bandwidth'],['addressingType','Static or dynamic'],['publicIp','Public IP address'],['subnetMask','Subnet mask / prefix'],['gateway','Gateway'],['dnsServers','DNS servers'],['demarcLocation','Demarc location'],['modemOnt','Modem / ONT'],['supportPhone','Carrier support phone'],['contractRenewal','Contract renewal','date']],
