  useEffect(()=>{if(!creating||createCategory!=='Configurations')return;const actions=document.querySelector('.core-asset-create-form .modal-actions');if(!actions)return;const host=document.createElement('div');host.className='configuration-create-host';actions.before(host);const root=createRoot(host);root.render(<ConfigurationCreateFields/>);return()=>{root.unmount();host.remove()}},[creating,createCategory]);
  useEffect(()=>{if(!creating||!industryAssetFields[createCategory])return;const actions=document.querySelector('.core-asset-create-form .modal-actions');if(!actions)return;const host=document.createElement('div');host.className='configuration-create-host industry-create-host';actions.before(host);const root=createRoot(host);root.render(<IndustryAssetCreateFields category={createCategory}/>);return()=>{root.unmount();host.remove()}},[creating,createCategory]);
  const createRecord=async event=>{event.preventDefault();setBusy(true);setError('');const body=Object.fromEntries(new FormData(event.currentTarget)),selectedClient=body.clientId,category=body.category;delete body.clientId;delete body.category;const categoryDetails={};Object.keys(body).filter(key=>key.startsWith('detail_')).forEach(key=>{categoryDetails[key.slice(7)]=body[key];delete body[key]});if(category==='Applications')body.type='other';else if(category==='Printing')body.type='printer';else if(category==='Wireless'){body.type='network';body.isWireless=true}else if(category==='Configurations')body.isConfiguration=true;else if(category==='LAN'||category==='WAN')body.type='network';if(industryAssetFields[category]){body.assetCategory=category;body.categoryDetails=categoryDetails}try{await apiJson(`/api/clients/${encodeURIComponent(selectedClient)}/${category==='Passwords'?'accounts':'assets'}`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});announceUnsaved(false);setCreating(false);setCreateCategory('Configurations');await reload()}catch(saveError){setError(saveError.message)}finally{setBusy(false)}};
