  const generateMfa=async()=>{setBusy(true);setError('');try{const value=await apiJson(`/api/client-accounts/${encodeURIComponent(selected.record.id)}/totp`);setMfa({...value,expiresAt:Date.now()+Number(value.expiresIn||30)*1000});setTick(Date.now())}catch(mfaError){setError(mfaError.message)}finally{setBusy(false)}};
  const owner=selected&&data.clients.find(item=>item.id===selected.record.clientId),seconds=mfa?Math.max(0,Math.ceil((mfa.expiresAt-tick)/1000)):0;
