  useEffect(()=>{if(!mfa)return;const timer=setInterval(()=>setTick(Date.now()),250);return()=>clearInterval(timer)},[mfa?.expiresAt]);
  const seconds=mfa?Math.max(0,Math.ceil((mfa.expiresAt-tick)/1000)):0,totalSeconds=Math.max(1,Number(mfa?.expiresIn||30)),progress=mfa?Math.max(0,Math.min(1,(mfa.expiresAt-tick)/(totalSeconds*1000))):0,tone=progress>.66?'green':progress>.33?'amber':'red';
  useEffect(()=>{if(mfa&&seconds===0&&!busy)generateMfa()},[seconds,mfa?.expiresAt,busy]);
  useEffect(()=>{if(kind!=='account'||!credentialDetails)return;const original=document.querySelector('.core-asset-screen .account-detail-status');if(!original)return;original.style.display='none';const host=document.createElement('div');host.className='credential-vault-host';original.after(host);const root=createRoot(host);root.render(<CredentialVaultFields credential={credentialDetails} record={record}/>);return()=>{root.unmount();host.remove();original.style.display=''}},[credentialDetails,kind,record.id,record.updatedAt,record.notes]);
  useEffect(()=>{if(kind!=='asset'||!record.isWireless)return;const original=document.querySelector('.core-asset-screen .core-asset-detail-grid');if(!original)return;original.style.display='none';const host=document.createElement('div');host.className='wireless-asset-host';original.after(host);const root=createRoot(host);root.render(<WirelessAssetFields record={record}/>);return()=>{root.unmount();host.remove();original.style.display=''}},[kind,record.id,record.isWireless,record.updatedAt]);
  useEffect(()=>{if(kind!=='asset'||!record.isConfiguration||record.isWireless)return;const original=document.querySelector('.core-asset-screen .core-asset-detail-grid');if(!original)return;original.style.display='none';const host=document.createElement('div');host.className='configuration-asset-host';original.after(host);const root=createRoot(host);root.render(<ConfigurationAssetFields record={record}/>);return()=>{root.unmount();host.remove();original.style.display=''}},[kind,record.id,record.isConfiguration,record.isWireless,record.updatedAt]);
